const seen = new Map();
for (let p = 1; p <= 30; p++) {
  const r: any = await tools.list_issues({ repo: "acme/api", state: "open", label: "security", page: p });
  const items: any[] = Array.isArray(r) ? r : (r?.items ?? []);
  if (items.length === 0) break;
  for (const i of items) seen.set(i.number, i);
}
const all = [...seen.values()];
const targets = all
  .filter((i) => i.state === "open" && !i.pull_request)
  .filter((i) => (i.labels ?? []).some((l: any) => l.name === "security"))
  .filter((i) => !i.assignee && (!i.assignees || i.assignees.length === 0))
  .map((i) => ({ number: i.number, title: i.title, author: i.user?.login }));
return { total_seen: all.length, targets };
```

